package com.matgorsel.pro;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import com.caverock.androidsvg.SVG;import java.io.*;import java.util.*;import java.util.zip.*;
public class MainActivity extends Activity {
 ImageView image; TextView status; Bitmap bitmap; PdfRenderer pdf; int page,bg,rotation; float zoom=1,x,y,lastX,lastY; File temp; boolean full; LinearLayout controls;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);controls=new LinearLayout(this);controls.setOrientation(1);root.addView(controls);status=new TextView(this);status.setText("Mat Görsel Pro • Dosya seçin");controls.addView(status);LinearLayout a=row(),c=row(),d=row();button(a,"Aç",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,1);});button(a,"−",()->scale(.8f));button(a,"+",()->scale(1.25f));button(a,"Sığdır",()->reset());button(a,"↻",()->{rotation+=90;apply();});button(c,"Önceki",()->{if(pdf!=null&&page>0){page--;render();}});button(c,"Sonraki",()->{if(pdf!=null&&page+1<pdf.getPageCount()){page++;render();}});button(c,"Zemin",()->{bg=(bg+1)%3;image.setBackgroundColor(new int[]{0xffeeeeee,0xffffffff,0xff222222}[bg]);});button(d,"PNG",()->save(false));button(d,"JPEG",()->save(true));button(d,"Tam ekran",()->{full=true;controls.setVisibility(View.GONE);});image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setBackgroundColor(0xffeeeeee);root.addView(image,new LinearLayout.LayoutParams(-1,0,1));ScaleGestureDetector detector=new ScaleGestureDetector(this,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector s){scale(s.getScaleFactor());return true;}});image.setOnTouchListener((v,e)->{detector.onTouchEvent(e);if(e.getActionMasked()==MotionEvent.ACTION_DOWN){lastX=e.getRawX();lastY=e.getRawY();}else if(e.getActionMasked()==MotionEvent.ACTION_MOVE&&e.getPointerCount()==1&&!detector.isInProgress()){x+=e.getRawX()-lastX;y+=e.getRawY()-lastY;lastX=e.getRawX();lastY=e.getRawY();apply();}return true;});setContentView(root);if(getIntent().getData()!=null)open(getIntent().getData());}
 LinearLayout row(){LinearLayout l=new LinearLayout(this);controls.addView(l);return l;}void button(LinearLayout l,String t,Runnable r){Button b=new Button(this);b.setText(t);b.setAllCaps(false);l.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->r.run());}void scale(float s){zoom=Math.max(.5f,Math.min(8,zoom*s));apply();}void reset(){zoom=1;x=y=0;rotation=0;apply();}void apply(){image.setScaleX(zoom);image.setScaleY(zoom);image.setRotation(rotation);image.setTranslationX(x);image.setTranslationY(y);}void show(Bitmap b){if(b==null)throw new IllegalArgumentException("Biçim desteklenmiyor");bitmap=b;image.setImageBitmap(b);reset();}void close(){if(pdf!=null){pdf.close();pdf=null;}if(temp!=null){temp.delete();temp=null;}}
 void render(){try(PdfRenderer.Page p=pdf.openPage(page)){float s=Math.min(2f,2400f/Math.max(p.getWidth(),p.getHeight()));Bitmap b=Bitmap.createBitmap(Math.max(1,(int)(p.getWidth()*s)),Math.max(1,(int)(p.getHeight()*s)),Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);p.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);show(b);status.setText("PDF • "+(page+1)+"/"+pdf.getPageCount());}catch(Exception e){error(e);}}
 void error(Exception e){status.setText("Hata: "+e.getMessage());}void save(boolean j){if(bitmap==null){status.setText("Önce bir görsel açın");return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType(j?"image/jpeg":"image/png");i.putExtra(Intent.EXTRA_TITLE,j?"gorsel.jpg":"gorsel.png");startActivityForResult(i,j?3:2);}
 protected void onActivityResult(int q,int r,Intent i){super.onActivityResult(q,r,i);if(r!=RESULT_OK||i==null)return;if(q==4){try(OutputStream o=getContentResolver().openOutputStream(i.getData())){if(pending!=null)o.write(pending);status.setText("Dosya kaydedildi; dönüştürücüde seçebilirsiniz.");}catch(Exception e){error(e);}finally{pending=null;}return;}if(q==1)open(i.getData());else if(q==2||q==3){try(OutputStream o=getContentResolver().openOutputStream(i.getData())){if(bitmap==null||!bitmap.compress(q==3?Bitmap.CompressFormat.JPEG:Bitmap.CompressFormat.PNG,95,o))throw new IOException("Kaydedilemedi");status.setText("Kaydedildi");}catch(Exception e){error(e);}}}
 void open(Uri u){try{String n="dosya";try(android.database.Cursor c=getContentResolver().query(u,null,null,null,null)){if(c!=null&&c.moveToFirst()){int k=c.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME);if(k>=0)n=c.getString(k);}}try(InputStream in=getContentResolver().openInputStream(u)){load(n,read(in,64*1024*1024));}}catch(Exception e){error(e);}}
 byte[] read(InputStream in,int limit)throws IOException{ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(o.size()+n>limit)throw new IOException("Dosya boyutu sınırı aşıldı");o.write(b,0,n);}return o.toByteArray();}
 void load(String name,byte[] data)throws Exception{try{loadLocal(name,data);}catch(Exception ex){String n=name.toLowerCase(Locale.ROOT);if(n.matches(".*\\.(eps|ps|tif|tiff|psd|ico|ai|heic|avif)$")){close();online(name,data);}else throw ex;}}
 void loadLocal(String name,byte[] data)throws Exception{close();bitmap=null;image.setImageDrawable(null);String n=name.toLowerCase(Locale.ROOT);if(n.endsWith(".zip")){ArrayList<String> names=new ArrayList<>();try(ZipInputStream z=new ZipInputStream(new ByteArrayInputStream(data))){ZipEntry e;while((e=z.getNextEntry())!=null){if(!e.isDirectory()&&e.getName().toLowerCase(Locale.ROOT).matches(".*\\.(png|jpg|jpeg|bmp|webp|gif|svg|pdf|ai|heic|avif|eps|ps|tif|tiff|psd|ico)$"))names.add(e.getName());if(names.size()>=500)break;}}new AlertDialog.Builder(this).setTitle("ZIP görselleri").setItems(names.toArray(new String[0]),(di,k)->{try(ZipInputStream z=new ZipInputStream(new ByteArrayInputStream(data))){ZipEntry e;while((e=z.getNextEntry())!=null)if(e.getName().equals(names.get(k))){load(e.getName(),read(z,64*1024*1024));break;}}catch(Exception ex){error(ex);}}).show();return;}
 if(n.endsWith(".pdf")||n.endsWith(".ai")){temp=File.createTempFile("view",".pdf",getCacheDir());try(FileOutputStream o=new FileOutputStream(temp)){o.write(data);}ParcelFileDescriptor fd=ParcelFileDescriptor.open(temp,ParcelFileDescriptor.MODE_READ_ONLY);try{pdf=new PdfRenderer(fd);}catch(Exception e){fd.close();throw e;}page=0;render();return;}
 if(n.matches(".*\\.(eps|ps|tif|tiff|psd|ico)$"))throw new IOException("Yerel çözücü yok");if(n.endsWith(".svg")){SVG svg=SVG.getFromInputStream(new ByteArrayInputStream(data));Picture p=svg.renderToPicture();int w=p.getWidth(),h=p.getHeight();if(w<=0||h<=0)throw new IOException("SVG boyutu geçersiz");float s=Math.min(3f,3000f/Math.max(w,h));Bitmap b=Bitmap.createBitmap(Math.max(1,(int)(w*s)),Math.max(1,(int)(h*s)),Bitmap.Config.ARGB_8888);Canvas cv=new Canvas(b);cv.scale(s,s);cv.drawPicture(p);show(b);}else{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,o);o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>3000)o.inSampleSize*=2;o.inJustDecodeBounds=false;show(BitmapFactory.decodeByteArray(data,0,data.length,o));if(Build.VERSION.SDK_INT>=28&&(n.endsWith(".gif")||n.endsWith(".webp"))){Drawable dr=ImageDecoder.decodeDrawable(ImageDecoder.createSource(java.nio.ByteBuffer.wrap(data)),(dec,info,src)->{int w=info.getSize().getWidth(),h=info.getSize().getHeight();float s=Math.min(1f,3000f/Math.max(w,h));dec.setTargetSize(Math.max(1,(int)(w*s)),Math.max(1,(int)(h*s)));});if(dr instanceof AnimatedImageDrawable){image.setImageDrawable(dr);((AnimatedImageDrawable)dr).start();}}}status.setText(name+" • "+bitmap.getWidth()+" × "+bitmap.getHeight());}
 void online(String name,byte[] data){new AlertDialog.Builder(this).setTitle("Çevrimiçi dönüştürme").setMessage(name+" yerel olarak açılamadı. Dosyayı seçtiğiniz çevrimiçi hizmete yükleyip PNG olarak indirmeniz gerekir. Hizmetin gizlilik ve ücret koşullarını kontrol edin. Dosya otomatik gönderilmez.").setNegativeButton("İptal",null).setPositiveButton("Dönüştürücüyü aç",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://cloudconvert.com/")));status.setText("PNG olarak dönüştürüp indirin; ardından Aç ile seçin.");}catch(Exception e){error(e);}}).setNeutralButton("Dosyayı kaydet",(d,w)->{pending=data;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/octet-stream");i.putExtra(Intent.EXTRA_TITLE,new File(name).getName());startActivityForResult(i,4);}).show();}
 byte[] pending;
 @Override public void onBackPressed(){if(full){full=false;controls.setVisibility(View.VISIBLE);}else super.onBackPressed();}protected void onDestroy(){close();super.onDestroy();}
}
